const $=id=>document.getElementById(id), view=$('view'), status=$('status');
const scene=new T.Scene();scene.background=new T.Color('#101820');
const backgroundColors={dark:'#101820',white:'#ffffff',sky:'#a6e3f5'};
function setBackground(value){
 const selected=Object.hasOwn(backgroundColors,value)?value:'dark';
 scene.background.set(backgroundColors[selected]);$('background').value=selected;
 try{localStorage.setItem('odr-skp-background',selected);}catch(e){}
}
let savedBackground='dark';try{savedBackground=localStorage.getItem('odr-skp-background')||'dark';}catch(e){}
setBackground(savedBackground);$('background').onchange=()=>setBackground($('background').value);
let camera=new T.PerspectiveCamera(42,1,.01,10000);camera.up.set(0,0,1);
const renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));view.prepend(renderer.domElement);
let controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;
scene.add(new T.HemisphereLight(0xffffff,0x526575,2.5));const sun=new T.DirectionalLight(0xffffff,2);sun.position.set(30,-30,60);scene.add(sun);
const modelGroup=new T.Group(), marks=new T.Group();scene.add(modelGroup,marks);
const pointer=new T.Mesh(new T.SphereGeometry(.065,12,8),new T.MeshBasicMaterial({color:0x67ffd4,depthTest:false}));pointer.renderOrder=99;pointer.visible=false;scene.add(pointer);
const ray=new T.Raycaster();let model,mode='navigate',zero=0,levels=[],measurements=[],pending=null,down,hit=null,extent=50;
let viewEdits={meshes:{},edges:{},groups:[],layers:[]};
let edgesVisible=false;try{edgesVisible=localStorage.getItem('odr-skp-edges')==='true';}catch(e){}
let rotationLocked=false;try{rotationLocked=localStorage.getItem('odr-skp-rotation-lock')==='true';}catch(e){}
const selected=new Set();let currentView='iso',depthPick=null;
function pickElement(e){if($('selectionTarget').value==='edges')return pickEdge(e);const rect=renderer.domElement.getBoundingClientRect();ray.setFromCamera(new T.Vector2((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1),camera);const indices=[...new Set(ray.intersectObjects(modelGroup.children.filter(o=>o.visible),false).map(h=>h.object.userData.index))];if(!indices.length){if(!e.shiftKey&&!e.ctrlKey)selected.clear();depthPick=null;updateSelection();return;}let index=indices[0];if(e.altKey&&depthPick&&Math.hypot(e.clientX-depthPick.x,e.clientY-depthPick.y)<6){const next=indices.indexOf(depthPick.index)+1;index=indices[next%indices.length];}depthPick={x:e.clientX,y:e.clientY,index};applySelection([index],e);updateSelection();msg('Seleccionado: '+model.meshes[index].name+' · '+indices.length+' piezas bajo el cursor.');}
function updateSelection(){if($('propertyInfo'))showSelectionProperties();
 modelGroup.children.forEach((mesh,i)=>mesh.material.emissive.set(selected.has(i)?'#966100':'#000000'));
 $('selectedItems').replaceChildren();const box=new T.Box3();
 for(const index of selected){const mesh=modelGroup.children[index];if(!mesh)continue;mesh.geometry.computeBoundingBox();box.union(mesh.geometry.boundingBox);const row=document.createElement('div');row.className='item';const button=document.createElement('button');button.textContent='×';button.title='Quitar de la selección';button.onclick=()=>{selected.delete(index);updateSelection();};const name=document.createElement('span');name.textContent='#'+(index+1)+' '+model.meshes[index].name;name.style.fontSize='12px';row.append(button,name);$('selectedItems').append(row);}
 if(!selected.size){$('selectionInfo').textContent='Ningún elemento seleccionado.';return;}
 const size=box.getSize(new T.Vector3());$('selectionInfo').textContent=`${selected.size} piezas seleccionadas · X ${fmt(size.x)} · Y ${fmt(size.y)} · Z ${fmt(size.z)} · Z mín ${fmt(box.min.z-zero)} / máx ${fmt(box.max.z-zero)}`;
}
function syncVisibility(){Array.from($('groups').querySelectorAll('input')).forEach((input,i)=>input.checked=modelGroup.children[i].visible);}
function restoreVisibility(){modelGroup.children.forEach(m=>m.visible=true);syncVisibility();msg('Todos los elementos visibles.');}
$('isolate').onclick=()=>{if(!selected.size)return msg('Selecciona una o más piezas para aislar.');modelGroup.children.forEach((m,i)=>m.visible=selected.has(i));syncVisibility();msg('Aisladas '+selected.size+' piezas. Usa Mostrar todo para recuperar el modelo.');};
$('hideSelected').onclick=()=>{if(!selected.size)return msg('Selecciona las piezas que quieres ocultar.');for(const i of selected)modelGroup.children[i].visible=false;syncVisibility();msg('Selección oculta. Usa Mostrar todo para recuperarla.');};
$('restoreVisible').onclick=restoreVisibility;$('clearSelected').onclick=()=>{clearEdgeSelection();selected.clear();depthPick=null;updateSelection();};
$('fitSelected').onclick=()=>{if(!selected.size)return msg('Selecciona primero una pieza.');const box=new T.Box3();for(const i of selected){const mesh=modelGroup.children[i];mesh.geometry.computeBoundingBox();box.union(mesh.geometry.boundingBox);}fit(currentView,[box.min.toArray(),box.max.toArray()]);};
const fmt=v=>(v*($('units').value==='cm'?100:1)).toFixed($('units').value==='cm'?2:3)+' '+$('units').value;
const msg=t=>status.textContent=t;
async function connectionState(){
 try{const r=await fetch('/health',{cache:'no-store',signal:AbortSignal.timeout(3000)});if(!r.ok)throw Error('Servidor anterior');const h=await r.json();if(h.service!=='odr-skp-viewer')throw Error('Servidor no compatible');$('connection').textContent='Lector SKP conectado · puedes abrir otros archivos';$('connection').style.background='#16574b';return true;}
 catch(e){$('connection').textContent='Lector SKP desconectado o desactualizado. Ejecuta ABRIR_VISOR.cmd y vuelve a pulsar Abrir otro SKP. El modelo en pantalla sigue disponible.';$('connection').style.background='#793b2c';return false;}
}
connectionState();setInterval(connectionState,15000);
let labelAnchors=[];
const signed=v=>(v>=0?'+':'')+fmt(v);
function download(text,name,type='text/plain'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),5000);}
function clear(group){for(const o of [...group.children]){o.traverse(child=>{child.geometry?.dispose();if(Array.isArray(child.material))child.material.forEach(m=>m.dispose());else child.material?.dispose();});group.remove(o);}}
function fit(which='iso',bounds=model.bounds){currentView=which;const b=new T.Box3(new T.Vector3(...bounds[0]),new T.Vector3(...bounds[1]));const center=b.getCenter(new T.Vector3());extent=b.getSize(new T.Vector3()).length();const d=Math.max(extent,.1)*1.35;controls.target.copy(center);camera.up.set(0,0,1);const dir={iso:[1,-1,.8],top:[0,0,1],bottom:[0,0,-1],front:[0,-1,0],back:[0,1,0],side:[1,0,0],left:[-1,0,0]}[which];if(which==='top')camera.up.set(0,1,0);camera.position.copy(center).add(new T.Vector3(...dir).normalize().multiplyScalar(d));camera.near=Math.max(extent/10000,.001);camera.far=Math.max(extent*100,100);if(camera.isOrthographicCamera){orthoHeight=2*d*Math.tan(42*Math.PI/360);camera.zoom=1;}resizeProjection();camera.updateProjectionMatrix();controls.update();}
function setMode(m){mode=m;controls.enableRotate=!rotationLocked&&m!=='select'&&m!=='hand';controls.mouseButtons.LEFT=m==='select'?null:m==='hand'?T.MOUSE.PAN:T.MOUSE.ROTATE;renderer.domElement.style.cursor=m==='hand'?'grab':'default';pending=null;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===m));$('tip').textContent={navigate:'Explorar · giro / desplazamiento / zoom',hand:'Mano · arrastra con botón izquierdo para desplazar · rueda para acercar',select:'Clic: seleccionar · Ctrl: añadir · Shift: quitar · Alt: recorrer profundidad',measure:'Selecciona el primer punto',dimension:'Cota: selecciona el primer punto',level:'Selecciona un punto para registrar su nivel',zero:'Selecciona el punto que representa ±0,00'}[m];pointer.visible=false;}
function loadModel(data){if(data.schema!=='odr-skp-mesh-1'||data.units!=='m')throw Error('Formato de modelo no válido');clear(modelGroup);selected.clear();depthPick=null;model=data;levels=[];measurements=[];$('candidates').replaceChildren();zero=0;$('zero').value=0;pending=null;
 viewEdits={meshes:{},edges:{},groups:[],layers:[]};renderUserGroups();renderLayers();sourceMeshes=data.meshes;$('selectionTarget').value='pieces';$('selectionDetail').value='groups';rebuildGeometry();fit();renderLists();setMode('navigate');}
let sourceMeshes=[];
function rebuildGeometry(){clear(propertyIsolation);clearEdgeSelection();clear(modelGroup);selected.clear();depthPick=null;pending=null;model.meshes=splitMeshes(sourceMeshes,$('selectionDetail').value);const data=model;
 data.meshes.forEach((m,i)=>{const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(m.positions,3));g.computeVertexNormals();const mesh=new T.Mesh(g,new T.MeshStandardMaterial({color:new T.Color().setHSL(.54+(i%5)*.018,.13,.57+(i%4)*.04),side:T.DoubleSide,roughness:.85,polygonOffset:true,polygonOffsetFactor:1,polygonOffsetUnits:1}));mesh.userData.index=i;modelGroup.add(mesh);});
 $('modelName').textContent=data.source;$('groups').replaceChildren();data.meshes.forEach((m,i)=>{const label=document.createElement('label');label.className='group';const input=document.createElement('input');input.type='checkbox';input.checked=true;input.onchange=()=>modelGroup.children[i].visible=input.checked;const span=document.createElement('span');span.textContent=m.name;span.title=m.name;label.append(input,span);$('groups').append(label);});applyViewEdits();updateSelection();updateEdges();msg(`${data.meshes.length} piezas seleccionables · ${data.stats.triangles.toLocaleString()} triángulos. Cambiar separación restablece la visibilidad y selección.`);}
$('selectionDetail').onchange=()=>{$('selectionTarget').value='pieces';rebuildGeometry();setMode('select');};
function marker(p,color){const m=new T.Mesh(new T.SphereGeometry(extent/450,10,8),new T.MeshBasicMaterial({color,depthTest:false}));m.position.fromArray(p);marks.add(m);}
function addLabel(p,text,measurement=false){const el=document.createElement('div');el.className='levelLabel'+(measurement?' measureLabel':'');el.textContent=text;$('labelLayer').append(el);labelAnchors.push({el,p:new T.Vector3(...p)});}
function drawDimension(m){const layout=dimensionLayout(m);if(!layout)return;const points=layout.segments.flat().map(p=>new T.Vector3(...p));const g=new T.BufferGeometry().setFromPoints(points);marks.add(new T.LineSegments(g,new T.LineBasicMaterial({color:0xffe08c,depthTest:false})));if($('labels').checked)addLabel(layout.label,fmt(layout.value),true);}
function drawMarks(){clear(marks);$('labelLayer').replaceChildren();labelAnchors=[];
 levels.forEach(l=>{marker(l.p,0xffc475);if($('labels').checked){addLabel(l.p,l.name+'\nCota '+signed(l.p[2]-zero)+' · Z '+fmt(l.p[2]));const [a,b]=model.bounds;const g=new T.BufferGeometry().setFromPoints([[a[0],a[1],l.p[2]],[b[0],a[1],l.p[2]],[b[0],b[1],l.p[2]],[a[0],b[1],l.p[2]],[a[0],a[1],l.p[2]]].map(p=>new T.Vector3(...p)));marks.add(new T.Line(g,new T.LineBasicMaterial({color:0xffc475,transparent:true,opacity:.45})));}});
 measurements.forEach(m=>{if(m.dimension){drawDimension(m);return;}marker(m.a,0x6de0c3);marker(m.b,0x6de0c3);const b=projectedEnd(m.a,m.b,m.axis);const g=new T.BufferGeometry().setFromPoints([new T.Vector3(...m.a),new T.Vector3(...b)]);const color={x:0xff7777,y:0x83df88,z:0x7baeff}[m.axis]||0x6de0c3;marks.add(new T.Line(g,new T.LineBasicMaterial({color,depthTest:false})));if(m.axis&&m.axis!=='3d'){const extension=new T.BufferGeometry().setFromPoints([new T.Vector3(...b),new T.Vector3(...m.b)]);const line=new T.Line(extension,new T.LineDashedMaterial({color, dashSize:.15,gapSize:.1,depthTest:false}));line.computeLineDistances();marks.add(line);}if($('labels').checked)addLabel(m.a.map((v,i)=>(v+b[i])/2),`${m.name} · ${(m.axis||'3d').toUpperCase()}\n${fmt(axisValue(m.a,m.b,m.axis))}`,true);});if(pending)marker(pending,0xffffff);
}
function renderLists(){ $('levelCount').textContent=levels.length;for(const [id,items] of [['levels',levels],['measurements',measurements]]){$(id).replaceChildren();items.forEach((item,i)=>{const row=document.createElement('div');row.className='item';const input=document.createElement('input');input.value=item.name;input.onchange=()=>{item.name=input.value.trim()||('Registro '+(i+1));input.value=item.name;drawMarks();};const remove=document.createElement('button');remove.textContent='×';remove.title='Eliminar registro';remove.onclick=()=>{items.splice(i,1);renderLists();};const small=document.createElement('small');if(id==='levels'){small.textContent=`Cota ${signed(item.p[2]-zero)} · Z SKP ${fmt(item.p[2])}`;}else{const c=components(item.a,item.b);small.textContent=`${(item.axis||'3d').toUpperCase()}: ${fmt(axisValue(item.a,item.b,item.axis))}\nΔX ${signed(c.dx)} · ΔY ${signed(c.dy)} · ΔZ ${signed(c.dz)}\n3D ${fmt(c.distance)} · XY ${fmt(c.horizontal)}`;small.style.whiteSpace='pre-line';}row.append(input,remove,small);
 if(id==='levels'){const label=document.createElement('label');label.className='storey';const check=document.createElement('input');check.type='checkbox';check.checked=item.storey!==false;check.onchange=()=>item.storey=check.checked;label.append(check,document.createTextNode(' Planta IFC / nivel Revit'));const z=document.createElement('input');z.type='number';z.step='.001';z.className='cotaInput';z.value=(item.p[2]-zero).toFixed(3);z.title='Editar cota relativa (metros)';z.onchange=()=>{if(z.value.trim()&&Number.isFinite(Number(z.value))){item.p[2]=Number(z.value)+zero;renderLists();}};row.append(label,document.createTextNode('Cota (m) '),z);}
 if(id==='measurements'){const label=document.createElement('label');label.className='storey';const check=document.createElement('input');check.type='checkbox';check.checked=!!item.dimension;check.onchange=()=>{item.dimension=check.checked;if(!Number.isFinite(item.offset))item.offset=1;renderLists();};label.append(check,document.createTextNode(' Mostrar como cota'));row.append(label);if(item.dimension){const sep=document.createElement('input');sep.type='number';sep.step='10';sep.className='cotaInput';sep.value=(Number.isFinite(item.offset)?item.offset:1)*100;sep.title='Separacion de la cota (cm); negativa cambia el lado';sep.onchange=()=>{if(sep.value.trim()&&Number.isFinite(Number(sep.value))){item.offset=Number(sep.value)/100;drawMarks();}};row.append(document.createTextNode('Separación (cm) '),sep);}}
 $(id).append(row);});}drawMarks();}
function selectPoint(e){const rect=renderer.domElement.getBoundingClientRect();ray.setFromCamera(new T.Vector2((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1),camera);const hits=ray.intersectObjects(modelGroup.children.filter(o=>o.visible),false);if(!hits.length)return null;const h=hits[0];let p=h.point.clone();if($('snap').value==='vertex'){let best=12,chosen=null;const raw=model.meshes[h.object.userData.index].positions;for(const idx of [h.face.a,h.face.b,h.face.c]){const v=new T.Vector3(...raw.slice(idx*3,idx*3+3));const proj=v.clone().project(camera);const distance=Math.hypot((proj.x+1)*rect.width/2-(e.clientX-rect.left),(1-proj.y)*rect.height/2-(e.clientY-rect.top));if(distance<best){best=distance;chosen=v;}}if(!chosen)return null;p=chosen;}return p.toArray();}
renderer.domElement.addEventListener('pointerdown',e=>{down=[e.clientX,e.clientY,e.button];if(mode==='select'&&e.button===0)renderer.domElement.setPointerCapture(e.pointerId);});
renderer.domElement.addEventListener('pointermove',e=>{if(mode==='hand'){pointer.visible=false;return;}if(mode==='select'){pointer.visible=false;if(down&&down[2]===0)showRectangle(e);return;}hit=selectPoint(e);pointer.visible=!!hit&&mode!=='navigate';if(hit){pointer.position.fromArray(hit);$('readout').textContent=`Z SKP ${fmt(hit[2])}\nCota ${signed(hit[2]-zero)}`;$('readout').style.whiteSpace='pre-line';let preview=pending?` · ${$('axis').value.toUpperCase()} ${fmt(axisValue(pending,hit,$('axis').value))}`:'';msg(`X ${fmt(hit[0])} · Y ${fmt(hit[1])} · Z ${fmt(hit[2])} · Cota ${signed(hit[2]-zero)}${preview}`);}else{$('readout').textContent='Z SKP —\nCota ±0,00 —';if(mode!=='navigate')msg('Acerca el cursor a un vértice o cambia a punto sobre superficie.');}});
renderer.domElement.addEventListener('pointerup',e=>{const start=down;down=null;selectionRect.style.display='none';if(!start||start[2]!==0||(mode==='navigate'||mode==='hand'))return;const dragged=Math.hypot(e.clientX-start[0],e.clientY-start[1])>4;if(mode==='select'){if(dragged)rectangleSelect(start,e);else pickElement(e);return;}if(dragged)return;const p=selectPoint(e);if(!p)return;if(mode==='zero'){zero=p[2];$('zero').value=zero;setMode('navigate');msg('Referencia ±0,00 definida.');}else if(mode==='level'){levels.push({name:'Nivel '+(levels.length+1),p});}else if(mode==='measure'||mode==='dimension'){if(!pending){pending=p;$('tip').textContent='Selecciona el segundo punto';}else{if(Math.hypot(...p.map((v,i)=>v-pending[i]))<1e-8){msg('El segundo punto debe ser distinto.');return;}if(mode==='dimension'&&axisValue(pending,p,$('axis').value)<1e-8){msg('La distancia en el eje elegido es cero. Selecciona otro punto.');return;}measurements.push({name:(mode==='dimension'?'Cota ':'Medida ')+(measurements.length+1),dimension:mode==='dimension',offset:Number($('dimensionOffset').value)/100,axis:$('axis').value,a:pending,b:p});pending=null;$('tip').textContent='Selecciona el primer punto';}}renderLists();});
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{setMode(b.dataset.mode);drawMarks();});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>fit(b.dataset.view));
$('units').onchange=()=>{renderLists();if($('selectionTarget').value==='edges')refreshEdgeSelection();else updateSelection();};$('labels').onchange=drawMarks;$('axis').onchange=()=>{pending=null;drawMarks();if(mode==='measure'||mode==='dimension')$('tip').textContent='Selecciona el primer punto · '+$('axis').value.toUpperCase();};$('zero').onchange=()=>{const z=Number($('zero').value);if(Number.isFinite(z)){zero=z;renderLists();$('candidates').replaceChildren();}};
$('addManual').onclick=()=>{if(!$('manualZ').value.trim())return msg('Escribe una cota en metros.');const z=Number($('manualZ').value);if(!Number.isFinite(z))return;levels.push({name:$('manualName').value.trim()||'Nivel '+(levels.length+1),p:[model.bounds[0][0],model.bounds[0][1],z+zero]});renderLists();};
const data=()=>({...sessionData(model,zero,levels,measurements),viewEdits});const meshes=()=>{if(!$('geometry').checked)return [];if($('exportSelected').checked&&!selected.size)throw Error('Selecciona piezas para exportarlas o desmarca Solo geometría seleccionada.');return model.meshes.filter((m,i)=>modelGroup.children[i].visible&&(!$('exportSelected').checked||selected.has(i))).map(m=>{const edit=viewEdits.meshes[meshKey(m)]||{},layer=layerFor(edit);return {...m,cadLayer:layer?.name||'SKP_MODELO',color:layer?.color||edit.color,transparency:edit.transparency??layer?.transparency??0,parameters:{...layer?.parameters,...edit.parameters}};});};
$('detectZ').onclick=()=>{try{const proposals=detectElevations(model.meshes.filter((m,i)=>modelGroup.children[i].visible),Number($('zTolerance').value)/100,Number($('zArea').value));$('candidates').replaceChildren();proposals.forEach(p=>{const row=document.createElement('div');row.className='item';const info=document.createElement('small');info.textContent=`Z ${fmt(p.z)} · Cota ${signed(p.z-zero)} · ${p.area.toFixed(1)} m²`;const add=document.createElement('button');add.textContent='Agregar';add.onclick=()=>{if(levels.some(l=>Math.abs(l.p[2]-p.z)<.001))return msg('Esta cota ya está registrada.');levels.push({name:'Nivel '+(levels.length+1),p:[...p.p],storey:true});renderLists();add.disabled=true;};row.append(add,info);$('candidates').append(row);});msg(`${proposals.length} cotas propuestas. Área acumulada de triángulos, puede incluir caras superpuestas. Revisa cuáles son plantas.`);}catch(e){msg(e.message);}};
for(const [id,ext,fn] of [['dxf','dxf',()=>dxf({...data(),cadEdges:cadExportEdges()},$('selectionTarget').value==='edges'&&$('exportSelected').checked?[]:meshes())],['ifc','ifc',()=>ifc(data(),meshes())],['csv','csv',()=>csv(data())],['revit','json',()=>JSON.stringify({...data(),levels:data().levels.filter(l=>l.storey)},null,2)]])$(id).onclick=()=>{try{if(!levels.length&&!measurements.length&&!(id==='dxf'&&cadExportEdges().length)&&!meshes().length)return msg('Registra niveles o medidas antes de exportar.');download(fn(),'levantamiento_skp.'+ext);msg('Exportación '+ext.toUpperCase()+' descargada.');}catch(e){msg('Error: '+e.message);}};
$('save').onclick=()=>download(JSON.stringify({...data(),bounds:model.bounds},null,2),'sesion_skp.json');$('restore').onclick=()=>$('session').click();
