$('nameSelection').onclick=()=>editSelected('name');$('colorSelection').onclick=()=>editSelected('color');$('resetSelectionStyle').onclick=()=>{for(const item of selectedEditItems())delete viewEdits[item.kind][item.key];applyViewEdits();if($('selectionTarget').value==='edges')refreshEdgeSelection();else updateSelection();};
$('createUserGroup').onclick=()=>{const items=selectedEditItems();if(!items.length)return msg('Selecciona los elementos del grupo.');const name=$('editName').value.trim()||'Grupo '+(viewEdits.groups.length+1);viewEdits.groups.push({name,type:$('selectionTarget').value,detail:$('selectionDetail').value,items});renderUserGroups();msg('Grupo '+name+' creado con '+items.length+' elementos.');};
function renderUserGroups(){if(!$('userGroups'))return;$('userGroups').replaceChildren();viewEdits.groups.forEach((group,i)=>{const row=document.createElement('div');row.className='item';const title=document.createElement('span');title.textContent=group.name+' · '+group.items.length+' elementos';const select=document.createElement('button');select.textContent='Seleccionar';select.onclick=()=>{if($('selectionDetail').value!==group.detail){$('selectionDetail').value=group.detail;rebuildGeometry();}$('selectionTarget').value=group.type;targetSelect.value=group.type;selected.clear();clearEdgeSelection();if(group.type==='edges'){edgesVisible=true;updateEdges();for(const item of group.items)edgeSelection.set(item.key,item);refreshEdgeSelection();}else{const keys=new Set(group.items.map(item=>item.key));model.meshes.forEach((m,index)=>{if(keys.has(meshKey(m))){selected.add(index);modelGroup.children[index].visible=true;}});syncVisibility();updateSelection();}setMode('select');msg('Grupo '+group.name+' seleccionado.');};const remove=document.createElement('button');remove.textContent='×';remove.title='Eliminar grupo';remove.onclick=()=>{viewEdits.groups.splice(i,1);renderUserGroups();};row.append(remove,select,title);$('userGroups').append(row);});}
function restoreViewEdits(d){if(!d)return;const safeColor=c=>typeof c==='string'&&/^#[0-9a-f]{6}$/i.test(c),point=p=>Array.isArray(p)&&p.length===3&&p.every(Number.isFinite);viewEdits={meshes:{},edges:{},groups:[],layers:[]};for(const kind of ['meshes','edges'])for(const [key,value] of Object.entries(d[kind]||{})){if(!value||typeof value!=='object')continue;const edit={};if(typeof value.name==='string')edit.name=value.name;if(safeColor(value.color))edit.color=value.color;if(typeof value.layer==='string')edit.layer=value.layer;if(Number.isFinite(value.transparency))edit.transparency=Math.max(0,Math.min(100,value.transparency));if(value.parameters&&typeof value.parameters==='object')edit.parameters=Object.fromEntries(Object.entries(value.parameters).filter(([k,v])=>typeof v==='string'));if(kind==='edges'){if(!point(value.a)||!point(value.b))continue;edit.a=value.a;edit.b=value.b;}viewEdits[kind][key]=edit;}if(Array.isArray(d.groups))viewEdits.groups=d.groups.filter(g=>g&&typeof g.name==='string'&&['pieces','faces','edges'].includes(g.type)&&['groups','surfaces','connected'].includes(g.detail)&&Array.isArray(g.items)&&g.items.every(item=>item&&typeof item.key==='string'&&(g.type!=='edges'||point(item.a)&&point(item.b))));if(Array.isArray(d.layers))viewEdits.layers=d.layers.filter(l=>l&&typeof l.id==='string'&&typeof l.name==='string'&&safeColor(l.color)).map(l=>({...l,transparency:Number.isFinite(l.transparency)?Math.max(0,Math.min(100,l.transparency)):0,visible:l.visible!==false}));applyViewEdits();renderUserGroups();renderLayers();}
toolbar('Editar',[{text:'Nombre / color',action:()=>{document.body.classList.remove('sidebarHidden');updatePanels();$('editName').scrollIntoView({block:'center'});$('editName').focus();}},{text:'Crear grupo',command:'createUserGroup'}]);renderUserGroups();

const propertyIsolation=new T.Group();scene.add(propertyIsolation);
function layerFor(edit){return viewEdits.layers.find(l=>l.id===edit?.layer);}
function selectedProperties(){return selectedEditItems().map(item=>{const edit=viewEdits[item.kind][item.key]||{},layer=layerFor(edit);return {nombre:edit.name|| (item.kind==='meshes'?model.meshes[item.i].name:'Arista'),capa:layer?.name||'Sin capa',transparencia:layer?.transparency??edit.transparency??0,parametros:{...layer?.parameters,...edit.parameters}};});}
function showSelectionProperties(){if(!$('propertyInfo'))return;$('propertyInfo').textContent=JSON.stringify(selectedProperties().slice(0,8),null,2);}
function modifySelected(fn){const items=selectedEditItems();if(!items.length)return msg('Selecciona elementos primero.');for(const item of items){const edit=viewEdits[item.kind][item.key]||{};if(item.kind==='edges'){edit.a=item.a;edit.b=item.b;}fn(edit,item);viewEdits[item.kind][item.key]=edit;}clear(propertyIsolation);applyViewEdits();syncVisibility();if($('selectionTarget').value==='edges')refreshEdgeSelection();else updateSelection();msg('Propiedades aplicadas a '+items.length+' elementos.');}
$('setTransparency').onclick=()=>{const t=Number($('editTransparency').value);if(!Number.isFinite(t)||t<0||t>100)return msg('Transparencia entre 0 y 100.');modifySelected(edit=>{edit.transparency=t;});};
$('assignLayer').onclick=()=>modifySelected(edit=>{if($('activeLayer').value)edit.layer=$('activeLayer').value;else delete edit.layer;});
$('newLayer').onclick=()=>{const name=$('layerName').value.trim();if(!name)return msg('Escribe un nombre de capa.');if(viewEdits.layers.some(l=>l.name.toLowerCase()===name.toLowerCase()))return msg('Ya existe una capa con ese nombre.');const id=crypto.randomUUID();viewEdits.layers.push({id,name,color:$('editColor').value,transparency:0,visible:true,parameters:{}});renderLayers();$('activeLayer').value=id;msg('Capa creada. Selecciona elementos y pulsa Asignar selección a capa.');};
function parameterInput(){const name=$('paramName').value.trim(),value=$('paramValue').value;return name?{name,value}:null;}
$('setParameter').onclick=()=>{const p=parameterInput();if(!p)return msg('Escribe el nombre del parámetro.');if(p.name.toLowerCase()==='nombre'){$('editName').value=p.value;editSelected('name');}else modifySelected(edit=>{edit.parameters={...edit.parameters,[p.name]:p.value};});showSelectionProperties();};
$('layerParameter').onclick=()=>{const layer=viewEdits.layers.find(l=>l.id===$('activeLayer').value),p=parameterInput();if(!layer||!p)return msg('Elige una capa y escribe un parámetro.');if(p.name.toLowerCase()==='nombre')layer.name=p.value;else layer.parameters={...layer.parameters,[p.name]:p.value};renderLayers();showSelectionProperties();};
function renderLayers(){if(!$('layerList'))return;const active=$('activeLayer').value;$('activeLayer').replaceChildren(new Option('Sin capa',''));$('layerList').replaceChildren();for(const layer of viewEdits.layers){$('activeLayer').append(new Option(layer.name,layer.id));const row=document.createElement('div');row.className='item';const name=document.createElement('input');name.value=layer.name;name.setAttribute('aria-label','Nombre de capa '+layer.name);name.onchange=()=>{layer.name=name.value.trim()||layer.name;renderLayers();};const color=document.createElement('input');color.type='color';color.value=layer.color;color.style.width='48px';color.setAttribute('aria-label','Color capa '+layer.name);const opacity=document.createElement('input');opacity.type='number';opacity.min=0;opacity.max=100;opacity.value=layer.transparency;opacity.style.width='65px';opacity.setAttribute('aria-label','Transparencia capa '+layer.name);const visible=document.createElement('input');visible.type='checkbox';visible.checked=layer.visible;visible.setAttribute('aria-label','Visible capa '+layer.name);const apply=()=>{clear(propertyIsolation);applyViewEdits();syncVisibility();showSelectionProperties();};color.onchange=()=>{layer.color=color.value;apply();};opacity.onchange=()=>{layer.transparency=Math.max(0,Math.min(100,Number(opacity.value)||0));apply();};visible.onchange=()=>{layer.visible=visible.checked;apply();};const isolate=document.createElement('button');isolate.textContent='Aislar';isolate.onclick=()=>isolateProperties((edit,m)=>edit?.layer===layer.id);const info=document.createElement('small');info.textContent='Visible · color · transparencia %';row.append(name,visible,color,opacity,isolate,info);$('layerList').append(row);}$('activeLayer').value=active;}
function isolateProperties(test){clear(propertyIsolation);let count=0;modelGroup.children.forEach((mesh,i)=>{const edit=viewEdits.meshes[meshKey(model.meshes[i])];mesh.visible=test(edit,model.meshes[i],mesh.material.color.getHexString());if(mesh.visible)count++;});for(const edit of Object.values(viewEdits.edges)){const layer=layerFor(edit),color=(layer?.color||edit.color||'#20343f').slice(1);if(!test(edit,{name:edit.name||''},color)||!edit.a||!edit.b)continue;propertyIsolation.add(new T.LineSegments(new T.BufferGeometry().setFromPoints([new T.Vector3(...edit.a),new T.Vector3(...edit.b)]),new T.LineBasicMaterial({color:'#'+color,transparent:true,opacity:1-(layer?.transparency??edit.transparency??0)/100})));count++;}syncVisibility();msg(count+' elementos aislados. Mostrar todo recupera el modelo.');}
$('isolateName').onclick=()=>{const name=$('filterName').value.trim().toLowerCase();if(!name)return msg('Escribe el nombre a buscar.');isolateProperties((edit,m)=>String(edit?.name||m.name).toLowerCase().includes(name));};
$('isolateColor').onclick=()=>{const color=$('editColor').value.slice(1).toLowerCase();isolateProperties((edit,m,current)=>current.toLowerCase()===color);};
const restoreAllHandler=$('restoreVisible').onclick;$('restoreVisible').onclick=()=>{clear(propertyIsolation);restoreAllHandler();applyViewEdits();syncVisibility();};
toolbar('Capas',[{text:'Capas / propiedades',action:()=>{document.body.classList.remove('sidebarHidden');updatePanels();$('layerName').scrollIntoView({block:'center'});$('layerName').focus();}},{text:'Aislar nombre',command:'isolateName'},{text:'Aislar color',command:'isolateColor'}]);renderLayers();

function filterEditedEdges(line){line.userData.fullEdges??=Array.from(line.geometry.attributes.position.array);const all=line.userData.fullEdges,out=[];for(let j=0;j<all.length;j+=6){const a=all.slice(j,j+3),b=all.slice(j+3,j+6);if(!viewEdits.edges[edgeKey(a,b)])for(let k=j;k<j+6;k++)out.push(all[k]);}line.geometry.setAttribute('position',new T.Float32BufferAttribute(out,3));line.geometry.computeBoundingSphere();}

function hasGeometryPoint(p,v){for(let i=0;i<p.length;i+=3)if(Math.hypot(p[i]-v[0],p[i+1]-v[1],p[i+2]-v[2])<.0001)return true;return false;}

function cadExportEdges(){if(!$('geometry').checked)return [];const candidates=$('exportSelected').checked&&$('selectionTarget').value==='edges'?[...edgeSelection.values()]:Object.values(viewEdits.edges);return candidates.filter(e=>layerFor(viewEdits.edges[edgeKey(e.a,e.b)]||e)?.visible!==false).map(e=>{const edit=viewEdits.edges[edgeKey(e.a,e.b)]||e,layer=layerFor(edit);return {...e,name:edit.name||'Arista',cadLayer:layer?.name||'SKP_ARISTAS',color:layer?.color||edit.color,transparency:edit.transparency??layer?.transparency??0,parameters:{...layer?.parameters,...edit.parameters}};});}
